10	  imported: 'Đã nhập {n} việc.',
11	  confirmReplace: 'Thay {n} việc hiện có bằng {m} việc trong file?',
12	  confirmReplaceUnreadable: 'Thay danh sách đã lưu không đọc được bằng {m} việc trong file?',
13	  confirmReplaceUnreadableAndUnsaved:
14	    'Thay danh sách đã lưu không đọc được và {n} việc bạn vừa thêm (chưa lưu) bằng {m} việc trong file?',
15	  emptyFile: 'File này không có việc nào, nên chưa nhập được. Danh sách của bạn vẫn giữ nguyên. Hãy chọn file sao lưu khác.',
16	  notBackup:
17	    'File này không phải file sao lưu của app, nên chưa nhập được. Danh sách của bạn vẫn giữ nguyên. ' +
18	    'Hãy chọn file tạo từ nút "Sao lưu ra file".',
19	  badTodo:
20	    'File sao lưu này bị lỗi, nên chưa nhập được việc nào. Danh sách của bạn vẫn giữ nguyên. Hãy chọn file sao lưu khác.',
