23	  emptyList: 'Chưa có việc nào. Nếu có file sao lưu, hãy bấm "Nhập từ file".',
24	  cannotReadFile: 'Không đọc được file này. Danh sách của bạn vẫn giữ nguyên. Hãy chọn lại file hoặc chọn file khác.',
25	  reading: 'Đang đọc file…',
26	  unreadable:
27	    'Không đọc được danh sách đã lưu trên trình duyệt này. Việc bạn thêm hoặc sửa lúc này sẽ không được lưu. ' +
28	    'Nếu có file sao lưu, hãy bấm "Nhập từ file".',
29	};
30	
31	const TODO_KEYS = ['id', 'title', 'done', 'createdAt'];
32	const FILE_KEYS = ['version', 'todos'];
33	
34	function fill(template, values) {
35	  return template.replace(/\{(\w+)\}/g, (_, k) => String(values[k]));
36	}
37	
