40	}
41	
42	function isObject(v) {
43	  return v !== null && typeof v === 'object' && !Array.isArray(v);
44	}
45	
46	function hasExactKeys(o, keys) {
47	  const own = Object.keys(o);
48	  return own.length === keys.length && keys.every((k) => Object.prototype.hasOwnProperty.call(o, k));
49	}
50	
51	function isValidTodo(t) {
52	  return (
53	    isObject(t) &&
54	    hasExactKeys(t, TODO_KEYS) &&
55	    typeof t.id === 'string' && t.id !== '' &&
56	    typeof t.title === 'string' && t.title.trim() !== '' &&
57	    typeof t.done === 'boolean' &&
58	    typeof t.createdAt === 'number' && Number.isFinite(t.createdAt)
59	  );
60	}
61	
62	function toBackupText(todos) {
63	  return JSON.stringify({ version: 1, todos: todos.map(pick) }, null, 2);
64	}
65	
66	// The customer's own day (local time), not UTC.
67	function backupFileName(date) {
68	  const pad = (n) => String(n).padStart(2, '0');
