80	    data = JSON.parse(text);
81	  } catch {
82	    return { ok: false, message: MESSAGES.notBackup };
83	  }
84	  if (!isObject(data) || !hasExactKeys(data, FILE_KEYS) || data.version !== 1 || !Array.isArray(data.todos)) {
