86	  }
87	  if (data.todos.length === 0) return { ok: false, message: MESSAGES.emptyFile };
88	  const ids = new Set();
89	  for (const t of data.todos) {
90	    if (!isValidTodo(t) || ids.has(t.id)) return { ok: false, message: MESSAGES.badTodo };
91	    ids.add(t.id);
92	  }
93	  return { ok: true, todos: data.todos.map(pick) };
94	}
95	
96	// null when nothing would be lost (empty list, saved list readable), so no confirmation is needed.
97	function confirmText({ readError, current, incoming }) {
98	  if (readError && current === 0) return fill(MESSAGES.confirmReplaceUnreadable, { m: incoming });
99	  if (readError) return fill(MESSAGES.confirmReplaceUnreadableAndUnsaved, { n: current, m: incoming });
100	  if (current === 0) return null;
101	  return fill(MESSAGES.confirmReplace, { n: current, m: incoming });
102	}
103	
104	// After add, toggle or remove. 'skipped' (saved list unreadable) shows nothing extra: the banner already says so.
105	function persist(store, todos) {
106	  return { message: store.save(todos) === 'failed' ? MESSAGES.notSaved : null };
107	}
108	
