110	// Writes only through store.replace, never store.save, so an unreadable saved list is replaced only here.
111	async function importBackup({ store, current, file, ask }) {
112	  const keep = (message) => ({ todos: current, message });
113	  if (file.size > MAX_IMPORT_BYTES) return keep(MESSAGES.fileTooBig);
114	  let text;
115	  try {
116	    text = await file.text();
117	  } catch {
118	    return keep(MESSAGES.cannotReadFile);
119	  }
120	  const parsed = parseBackup(text);
121	  if (!parsed.ok) return keep(parsed.message);
122	  const question = confirmText({ readError: store.readError, current: current.length, incoming: parsed.todos.length });
123	  if (question !== null && !(await ask(question))) return keep(null);
124	  if (store.replace(parsed.todos) !== 'saved') return keep(MESSAGES.notSaved);
125	  return { todos: parsed.todos, message: fill(MESSAGES.imported, { n: parsed.todos.length }) };
126	}
127	
