1	// A todo has: id, title, done, createdAt. No due date, no tags, no owner.
2	// Saving and importing decisions live in backup.js (persist, importBackup); this file only wires them to the page.
3	let todos = store.load().todos;
4	let filter = 'all';
5	
6	const $ = (sel) => document.querySelector(sel);
7	
8	function add(title) {
9	  todos.push({ id: crypto.randomUUID(), title: title.trim(), done: false, createdAt: Date.now() });
10	  commit();
11	}
12	
13	function toggle(id) {
14	  const t = todos.find((x) => x.id === id);
15	  if (t) t.done = !t.done;
16	  commit();
17	}
18	
19	function remove(id) {
20	  todos = todos.filter((x) => x.id !== id);
21	  commit();
22	}
23	
24	function commit() {
25	  show(persist(store, todos).message);
26	  render();
27	}
28	
29	function show(message) {
30	  $('#message').textContent = message || '';
31	}
32	
33	function visible() {
34	  if (filter === 'open') return todos.filter((t) => !t.done);
35	  if (filter === 'done') return todos.filter((t) => t.done);
36	  return todos;
37	}
38	
39	function render() {
40	  const list = $('#list');
41	  list.innerHTML = '';
42	  for (const t of visible()) {
43	    const li = document.createElement('li');
44	    li.className = t.done ? 'done' : '';
45	    li.innerHTML = `<label><input type="checkbox" ${t.done ? 'checked' : ''}> <span></span></label><button aria-label="Xoá">×</button>`;
46	    li.querySelector('span').textContent = t.title;
47	    li.querySelector('input').onchange = () => toggle(t.id);
48	    li.querySelector('button').onclick = () => remove(t.id);
49	    list.append(li);
50	  }
51	  const open = todos.filter((t) => !t.done).length;
